    <div class="col-md-4"><label class="form-label" for="com_quantidade">Quantidade</label><input class="form-control" type="number" step="0.01" min="0.01" id="com_quantidade" name="com_quantidade" value="<?= escapar(formatar_decimal_input($compra['com_quantidade'] ?? '')) ?>"></div>
