    <div class="col-12"><label class="form-label" for="com_observacoes">Observações</label><textarea class="form-control" id="com_observacoes" name="com_observacoes" rows="3" maxlength="2000"><?= escapar($compra['com_observacoes'] ?? '') ?></textarea></div>
